/// <summary>
/// MPJ_2149_Fixed asset disposal report.
/// </summary>
[ExtensionOf(classStr(AssetDisposalDp))]
final class METAssetDisposalDp_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ_2149_Fixed asset disposal report.
    /// </summary>
    public void processReport()
    {
        AssetDisposal       assetDisposal;
        AssetDisposalTmp    assetDisposalTmp = this.getAssetDisposalTmp();
        Query               query;
        QueryRun            queryRun;

        query       = this.parmQuery();
        queryRun    = new QueryRun(query);

        next processReport();

        while (queryRun.next())
        {
            assetDisposal = queryRun.get(tableNum(AssetDisposal)) as AssetDisposal;

            ttsbegin;
            select forupdate assetDisposalTmp
                where assetDisposalTmp.AssetId == assetDisposal.AssetId
                &&    assetDisposalTmp.BookId  == assetDisposal.BookId;
            {
                assetDisposalTmp.CostCenter = this.getCostCenterByDefaultDimension(assetDisposal);
                assetDisposalTmp.Pillar     = this.getPillarByDefaultDimension(assetDisposal);
                assetDisposalTmp.update();
            }
            ttscommit;

        }
        
    }

    /// <summary>
    /// MPJ_2149_Fixed asset disposal report.
    /// </summary>
    /// <param name = "_assetDisposal">
    ///  get AssetDisposal table buffer
    /// </param>
    /// <returns>
    /// return cost center value
    /// </returns>
    public str getCostCenterByDefaultDimension(AssetDisposal _assetDisposal)
    {
        DimensionAttributeValueSetStorage   dimStorage;
        Name                                costCenter;
        Counter                             i;

        dimStorage = DimensionAttributeValueSetStorage::find(_assetDisposal.DefaultDimension);

        for (i= 1 ; i<= dimStorage.elements() ; i++)
        {
            
            if(DimensionAttribute::find(dimStorage.getAttributeByIndex(i)).Name == 'COSTCENTRE')
            {
                costCenter = dimStorage.getDisplayValueByIndex(i);
            }
        }

        return costCenter;
    }

    /// <summary>
    /// MPJ_2149_Fixed asset disposal report.
    /// </summary>
    /// <param name = "_assetDisposal">
    /// get AssetDisposal table buffer
    /// </param>
    /// <returns>
    /// return Pillar value
    /// </returns>
    public str getPillarByDefaultDimension(AssetDisposal _assetDisposal)
    {
        DimensionAttributeValueSetStorage   dimStorage;
        Name                                pillar;
        Counter                             i;

        dimStorage = DimensionAttributeValueSetStorage::find(_assetDisposal.DefaultDimension);

        for (i= 1 ; i<= dimStorage.elements() ; i++)
        {
            
            if(DimensionAttribute::find(dimStorage.getAttributeByIndex(i)).Name == 'PILLAR')
            {
                pillar = dimStorage.getDisplayValueByIndex(i);
            }
        }

        return pillar;
    }
